import {ToolRegistry} from './registry.js';
import Ajv from 'ajv';
import {jest} from '@jest/globals';

describe('ToolRegistry input validation', () => {
  it('rejects missing required input before invoking the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;

    registry.register(weatherDefinition(), async () => {
      executorCalls += 1;
      return 'sunny';
    });

    const response = await registry.execute('weather', {});

    expect({result: response.result, executorCalls}).toEqual({
      result: expect.stringMatching(/location.*required/i),
      executorCalls: 0,
    });
  });

  it('passes valid input and undeclared properties through unchanged exactly once', async () => {
    const registry = new ToolRegistry();
    const input = {location: 'Berlin', unit: 'celsius'};
    const received: Array<Record<string, unknown>> = [];
    registry.register(weatherDefinition(), async toolInput => {
      received.push(toolInput);
      return 'sunny';
    });

    await registry.execute('weather', input);

    expect(received).toEqual([input]);
  });

  it('names the field and expected type when rejecting a wrong-typed property', async () => {
    const response = await executeWeather({location: 42});

    expect(response.result).toBe('location must be string');
  });

  it('names the enum constraint when rejecting a value outside the enum', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: 'Get weather',
        inputSchema: {
          type: 'object',
          properties: {unit: {type: 'string', enum: ['celsius', 'fahrenheit']}},
        },
      },
      async () => 'sunny'
    );

    const response = await registry.execute('weather', {unit: 'kelvin'});

    expect(response.result).toBe('unit must satisfy enum constraint');
  });

  it('reports nested property paths in validation rejections', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'profile',
        description: 'Read a profile',
        inputSchema: {
          type: 'object',
          properties: {profile: {type: 'object', properties: {name: {type: 'string'}}}},
        },
      },
      async () => 'ok'
    );

    const response = await registry.execute('profile', {profile: {name: 42}});

    expect(response.result).toBe('profile.name must be string');
  });

  it('reports the full nested property path when a required property is missing', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'profile',
        description: 'Read a profile',
        inputSchema: {
          type: 'object',
          properties: {profile: {type: 'object', required: ['name']}},
        },
      },
      async () => 'ok'
    );

    const response = await registry.execute('profile', {profile: {}});

    expect(response.result).toBe('profile.name required');
  });

  it('does not prefix top-level validation paths with punctuation', async () => {
    const response = await executeWeather({location: 42});

    expect(response.result.startsWith('.')).toBe(false);
  });

  it('reuses a static schema validator across ten executions', async () => {
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    const schema = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    const registry = new ToolRegistry();
    registry.register({name: 'weather', description: 'Get weather', inputSchema: schema}, async () => 'sunny');
    const compileMock = compile.mock;
    const compileCountAfterRegister = compileMock.calls.length;

    await Promise.all(Array.from({length: 10}, () => registry.execute('weather', {location: 'Berlin'})));

    expect({compileCountAfterRegister, compileCountAfterExecutions: compileMock.calls.length}).toEqual({
      compileCountAfterRegister: 1,
      compileCountAfterExecutions: 1,
    });
    compile.mockRestore();
  });
});

function weatherDefinition() {
  return {
    name: 'weather',
    description: 'Get weather',
    inputSchema: {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    },
  };
}

async function executeWeather(input: Record<string, unknown>) {
  const registry = new ToolRegistry();
  registry.register(weatherDefinition(), async () => 'sunny');
  return registry.execute('weather', input);
}

#!/usr/bin/env node
// Emits the Lore test-command `list` shape: a single JSON array of
// {id, name, file} objects, one per test, and nothing else on stdout.
// Jest cannot resolve test names without executing them - there is no
// dry-run - so the suite is run once with --json written to a temp file and
// progress sent to stderr, keeping stdout pure.
// The id is "<repo-relative-file>::<full test name>" - stable across runs,
// and exactly what the run command's {selector} splits back apart.
import {execFileSync} from 'node:child_process';
import {readFileSync, rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join, relative} from 'node:path';
import process from 'node:process';

const reportFile = join(tmpdir(), `hal-engine-jest-report-${process.pid}.json`);

try {
  execFileSync('npx', ['jest', '--json', `--outputFile=${reportFile}`], {
    cwd: process.cwd(),
    stdio: ['ignore', 'ignore', 'inherit'],
    // The suite runs as ESM; jest needs the flag in every spawn, not just npm test.
    env: {...process.env, NODE_OPTIONS: `${process.env.NODE_OPTIONS ?? ''} --experimental-vm-modules`.trim()},
  });
} catch {
  // A failing test still produces a full report, and listing must not depend
  // on the suite being green. An unreadable report below is the real failure.
}

let report;

try {
  report = JSON.parse(readFileSync(reportFile, 'utf8'));
} catch (error) {
  process.stderr.write(`jest produced no readable report at ${reportFile}: ${error.message}\n`);
  process.exit(1);
} finally {
  rmSync(reportFile, {force: true});
}

const tests = report.testResults.flatMap(suite => {
  const file = relative(process.cwd(), suite.name);

  return suite.assertionResults.map(assertion => ({
    id: `${file}::${assertion.fullName}`,
    name: assertion.fullName,
    file,
  }));
});

process.stdout.write(`${JSON.stringify(tests)}\n`);
#!/usr/bin/env node
// Runs exactly one test for the Lore test-command interface. The selector is
// "<repo-relative-file>::<full test name>" as emitted by lore-list-tests.mjs.
// Jest's -t flag is a regex matched against the full name, so the name is
// escaped and anchored - a name containing (parens) or {500} must match
// literally - and the file is passed with --runTestsByPath, which takes a path
// rather than the regex a bare positional argument would be.
// A selector that matches nothing is a failure, never a silently green run of
// an empty suite.
import {execFileSync} from 'node:child_process';
import {readFileSync, rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import process from 'node:process';

const selector = process.argv[2];

if (!selector || !selector.includes('::')) {
  process.stderr.write('usage: lore-run-test.mjs "<file>::<full test name>"\n');
  process.exit(2);
}

const separator = selector.indexOf('::');
const file = selector.slice(0, separator);
const name = selector.slice(separator + 2);
const escaped = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

const reportFile = join(tmpdir(), `hal-engine-jest-run-${process.pid}.json`);

let runFailed = false;

try {
  execFileSync(
    'npx',
    [
      'jest',
      '--runTestsByPath',
      file,
      '-t',
      `^${escaped}$`,
      '--json',
      `--outputFile=${reportFile}`,
      '--coverage',
      '--coverageReporters=lcov',
    ],
    {
      cwd: process.cwd(),
      stdio: ['ignore', 'inherit', 'inherit'],
      // The suite runs as ESM; jest needs the flag in every spawn, not just npm test.
      env: {...process.env, NODE_OPTIONS: `${process.env.NODE_OPTIONS ?? ''} --experimental-vm-modules`.trim()},
    }
  );
} catch {
  runFailed = true;
}

let report;

try {
  report = JSON.parse(readFileSync(reportFile, 'utf8'));
} catch (error) {
  process.stderr.write(`jest produced no readable report at ${reportFile}: ${error.message}\n`);
  process.exit(1);
} finally {
  rmSync(reportFile, {force: true});
}

// Every test in the file that -t did not select is reported as pending, so the
// count that matters is the ones actually executed.
const ran = report.numTotalTests - (report.numPendingTests ?? 0);

if (ran === 0) {
  process.stderr.write(`selector matched no test: ${selector}\n`);
  process.exit(1);
}

process.exit(runFailed || report.numFailedTests > 0 ? 1 : 0);
